parameters.functionCode:
// MASTER TASK CONTROLLER - finds what needs to be done
const tasks = $input.first().json.result || [];
console.log(`🔍 Analyzing ${tasks.length} tasks for Due Diligence workflow`);

// All 20 sections that need individual tasks
const ALL_SECTIONS = [
  "Introduction & Engagement Context",
  "Methodology & Reliability Levels", 
  "Company Overview",
  "Business Model & Unit Economics",
  "Products & Technology",
  "Target Market & Competitive Set",
  "Financials",
  "Cash, Burn, Runway",
  "Revenue Quality & Client Cohorts",
  "Partnerships & Ecosystem",
  "Intellectual Property",
  "Legal & Regulatory",
  "Governance & Board Effectiveness",
  "Capital Structure & Dilution",
  "Risk Matrix & Mitigations",
  "Gaps, Uncertainties & Disclaimers",
  "Scenario Analysis",
  "Strategic Options",
  "Recommendations & Next Steps",
  "Source Map & Integrity Log"
];

// Find master due diligence task (contains company info)
let masterTask = null;
for (const task of tasks) {
  const title = task.title ? task.title.toString() : '';
  const description = task.description ? task.description.toString() : '';

  // Master task: "Due Diligence: [Company Name]"
  if (title.toLowerCase().includes('due diligence:') && description.includes('http')) {
    masterTask = {
      id: task.id,
      title: title,
      description: description,
      company_name: title.replace(/due diligence:\s*/i, '').trim(),
      website_url: description.match(/https?:\/\/[^\s]+/)?.[0] || 'Not provided'
    };
    break;
  }
}

if (!masterTask) {
  console.log('ℹ️ No master Due Diligence task found - workflow completed');
  throw new Error('No master Due Diligence task found');
}

console.log(`📋 Found master task for: ${masterTask.company_name}`);

// Check if final report is already generated
if (masterTask.description.includes('🎯 FINAL PDF REPORT ATTACHED')) {
  console.log('✅ Final report already generated - workflow complete');
  throw new Error('Final report already generated');
}

// Find existing section tasks for this company
const sectionTasks = [];
for (const task of tasks) {
  const title = task.title ? task.title.toString() : '';

  // Section task format: "[Company Name] - [Section Name]"
  if (title.includes(`${masterTask.company_name} - `)) {
    const sectionName = title.replace(`${masterTask.company_name} - `, '').trim();
    sectionTasks.push({
      id: task.id,
      section_name: sectionName,
      status: task.description?.includes('✅ APPROVED JSON') ? 'approved' : 'pending'
    });
  }
}

console.log(`📊 Found ${sectionTasks.length} section tasks`);

// Find next action needed
const approvedSections = sectionTasks.filter(t => t.status === 'approved').map(t => t.section_name);
const pendingSections = sectionTasks.filter(t => t.status === 'pending');

// Check if we need to create section tasks
for (const section of ALL_SECTIONS) {
  const exists = sectionTasks.find(t => t.section_name === section);
  if (!exists) {
    console.log(`🎯 Need to create section task: ${section}`);
    return {
      json: {
        action: "CREATE_SECTION_TASK",
        master_task: masterTask,
        section_name: section,
        section_index: ALL_SECTIONS.indexOf(section),
        total_sections: ALL_SECTIONS.length
      }
    };
  }
}

// Check if we have pending section to process
if (pendingSections.length > 0) {
  const nextTask = pendingSections[0];
  console.log(`🎯 Processing section: ${nextTask.section_name}`);
  return {
    json: {
      action: "PROCESS_SECTION",
      master_task: masterTask,
      section_task_id: nextTask.id,
      section_name: nextTask.section_name,
      section_index: ALL_SECTIONS.indexOf(nextTask.section_name),
      total_sections: ALL_SECTIONS.length,
      approved_sections: approvedSections
    }
  };
}

// All sections approved - generate final PDF
if (approvedSections.length === ALL_SECTIONS.length) {
  console.log(`🎉 All ${ALL_SECTIONS.length} sections approved - generating PDF`);
  return {
    json: {
      action: "GENERATE_FINAL_PDF",
      master_task: masterTask,
      section_tasks: sectionTasks,
      approved_sections: approvedSections,
      total_sections: ALL_SECTIONS.length
    }
  };
}

console.log(`⏳ Waiting for sections to complete: ${approvedSections.length}/${ALL_SECTIONS.length}`);
throw new Error(`Waiting for sections: ${approvedSections.length}/${ALL_SECTIONS.length} complete`);

