}

parameters.functionCode:
// MAKER OUTPUT PROCESSOR
const sectionData = $('Prepare Section Data').first().json;
const makerResponse = $('Maker Agent').first().json.response;

console.log(`🤖 Processing Maker output for: ${sectionData.section_name}`);

// Parse Maker JSON with robust error handling
let makerOutput;
try {
  const jsonMatch = makerResponse.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    makerOutput = JSON.parse(jsonMatch[0]);
    console.log('✅ Maker JSON parsed successfully');
  } else {
    throw new Error('No JSON found in response');
  }
} catch (error) {
  console.log(`⚠️ Maker JSON parsing failed: ${error.message}`);
  // Fallback structure
  makerOutput = {
    section: sectionData.section_name,
    content: makerResponse,
    citations: ['AI response', 'Knowledge Base']
  };
}

// Validate output quality
if (!makerOutput.content || makerOutput.content.trim().length < 100) {
  console.log('⚠️ Maker content too short, enhancing...');
  makerOutput.content = `## ${sectionData.section_name}\n\n${sectionData.section_prompt}\n\nBased on available materials for ${sectionData.master_task.company_name}:\n\n${makerResponse}\n\n*Analysis based on available Knowledge Base materials.*`;
}

return {
  json: {
    ...sectionData,
    maker_output: makerOutput,
    maker_status: 'completed'
  }
};

