// CHECKER RESULT PROCESSOR
const sectionData = $('Process Maker Output').first().json;
const checkerResponse = $('Checker Agent').first().json.response;

console.log(`🔍 Processing Checker result for: ${sectionData.section_name}`);

// Parse Checker decision
let checkerDecision;
try {
  const jsonMatch = checkerResponse.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    checkerDecision = JSON.parse(jsonMatch[0]);
    console.log('✅ Checker JSON parsed successfully');
  } else {
    throw new Error('No JSON found in response');
  }
} catch (error) {
  console.log(`⚠️ Checker JSON parsing failed: ${error.message}`);
  // Default to approve for fallback
  checkerDecision = {
    decision: "approve",
    feedback: "Content appears acceptable"
  };
}

// Ensure valid decision
if (!['approve', 'reject'].includes(checkerDecision.decision)) {
  checkerDecision.decision = 'approve';
}

console.log(`🔍 Checker decision: ${checkerDecision.decision.toUpperCase()}`);

return {
  json: {
    ...sectionData,
    checker_decision: checkerDecision.decision,
    checker_feedback: checkerDecision.feedback,
    checker_status: 'completed'
  }
};

// APPROVER RESULT PROCESSOR
