try {
  const jsonMatch = approverResponse.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    approverDecision = JSON.parse(jsonMatch[0]);
    console.log('✅ Approver JSON parsed successfully');
  } else {
    throw new Error('No JSON found in response');
  }
} catch (error) {
  console.log(`⚠️ Approver JSON parsing failed: ${error.message}`);
  // Default to approve for fallback
  approverDecision = {
    decision: "approve",
    feedback: "Section approved for business use"
  };
}

// Ensure valid decision
if (!['approve', 'reject'].includes(approverDecision.decision)) {
  approverDecision.decision = 'approve';
}

console.log(`💼 Approver decision: ${approverDecision.decision.toUpperCase()}`);

return {
  json: {
    ...sectionData,
    approver_decision: approverDecision.decision,
    approver_feedback: approverDecision.feedback,
    approver_status: 'completed',
    mca_complete: approverDecision.decision === 'approve'
  }
};

